"""Embed the Icon256 UI only when its usermod is built. No filesystem upload needed."""
# AI: below section was generated by an AI
import gzip
from pathlib import Path

Import("env")
root = Path(env.subst("$PROJECT_DIR"))
ui = root / "usermods/usermod_v2_icon256_wordclock/ui"
html = (ui / "index.html").read_text()
script = (ui / "app.js").read_text().replace("__GERMAN_TRANSLATIONS__", (ui / "de.json").read_text())
html = html.replace('<script src="app.js"></script>', '<script>' + script + '</script>')
for name in ('updater.js', 'update-ui.js'):
    html = html.replace(f'<script src="{name}"></script>', '<script>' + (ui / name).read_text() + '</script>')
data = gzip.compress(html.encode(), mtime=0)
target = root / "wled00/html_icon256.h"
content = '// Generated by the Icon256 usermod build. Do not edit.\n#pragma once\nconst uint8_t ICON256_PAGE[] PROGMEM = {\n'
content += ',\n'.join(','.join(str(b) for b in data[i:i+24]) for i in range(0, len(data), 24)) + '\n};\n'
if not target.exists() or target.read_text() != content:
    target.write_text(content)
print(f"Icon256 UI: {len(data)} compressed bytes")
# AI: end
